// Extract last 3 captions from Instagram page HTML/JSON
const handle = $('Split by Handle').item.json.handles;
const raw = $input.item.json.contents || '';

let captions = [];
try {
  const parsed = JSON.parse(raw);
  const edges = parsed?.graphql?.user?.edge_owner_to_timeline_media?.edges
    || parsed?.data?.user?.edge_owner_to_timeline_media?.edges
    || [];
  captions = edges.slice(0, 3).map(e => ({
    caption: e?.node?.edge_media_to_caption?.edges?.[0]?.node?.text || '',
    postUrl: 'https://www.instagram.com/p/' + (e?.node?.shortcode || '') + '/'
  }));
} catch {
  const metaMatches = raw.matchAll(/<meta property="og:description" content="([^"]+)"/g);
  for (const m of metaMatches) {
    captions.push({ caption: m[1], postUrl: 'https://www.instagram.com/' + handle + '/' });
    if (captions.length >= 2) break;
  }
}

if (captions.length === 0) return [];

return captions.map(c => ({ json: { handle, caption: c.caption, postUrl: c.postUrl } }));

