const groqResponse = $input.item.json;
const postUrl = $('Parse Captions').item.json.postUrl;
const handle = $('Parse Captions').item.json.handle;

let extracted;
try {
  const content = groqResponse?.choices?.[0]?.message?.content || '{"found":false}';
  extracted = JSON.parse(content);
} catch {
  return [{ json: { found: false } }];
}

if (!extracted.found) return [{ json: { found: false } }];

let startsAt;
try {
  const d = new Date(`${extracted.date}T${extracted.time || '10:00'}:00+02:00`);
  if (isNaN(d.getTime())) throw new Error('invalid date');
  startsAt = d.toISOString();
} catch {
  return [{ json: { found: false } }];
}

const inThirtyDays = Date.now() + 30 * 86400000;
if (new Date(startsAt).getTime() < Date.now() || new Date(startsAt).getTime() > inThirtyDays) {
  return [{ json: { found: false } }];
}

const ACCENTS = { midnightrunnersbarcelona:'lavender', 'runners.barcelona':'mint', b3tterrunclub:'butter', ordinaryrunclub:'peach', razzeclub:'coral', galacticrunclub:'lavender', sunriserunnersbarcelona:'butter', clubrodeobcn:'mint' };

return [{ json: {
  found: true,
  id: postUrl,
  title: extracted.title || `Run · ${handle}`,
  club: extracted.club || handle,
  meeting_point: extracted.meetingPoint || null,
  starts_at: startsAt,
  distance: extracted.distance || null,
  post_url: postUrl,
  accent: ACCENTS[handle] || 'coral'
} }];
